create table if not exists public.erp_font_settings(id bigint generated by default as identity primary key,setting_key text unique not null,settings_json jsonb not null default '{}'::jsonb,updated_by text,updated_at timestamptz default now());
create table if not exists public.erp_autofill_settings(id bigint generated by default as identity primary key,setting_key text unique not null,settings_json jsonb not null default '{}'::jsonb,updated_by text,updated_at timestamptz default now());
alter table public.erp_font_settings enable row level security;alter table public.erp_autofill_settings enable row level security;
drop policy if exists "Public all erp_font_settings" on public.erp_font_settings;create policy "Public all erp_font_settings" on public.erp_font_settings for all using(true) with check(true);
drop policy if exists "Public all erp_autofill_settings" on public.erp_autofill_settings;create policy "Public all erp_autofill_settings" on public.erp_autofill_settings for all using(true) with check(true);
